ASSET = 'src/mixel_gui_launch.rs'
SCRIPTS = Path(__file__).resolve(strict=True).parent

def digest(data):
    return hashlib.sha256(data).hexdigest()

def prior(name):
    path=SCRIPTS/name
    info=path.lstat()
    if not stat.S_ISREG(info.st_mode) or info.st_nlink!=1 or getattr(info,'st_file_attributes',0)&0x400:
        raise RuntimeError('Unsafe launch prior verifier')
    raw=path.read_bytes();logical=raw.replace(b'\r\n',b'\n')
    if b'\r' in logical or (b'\r\n' in raw and logical.replace(b'\n',b'\r\n')!=raw) or digest(logical)!=PRIOR[name]:
        raise RuntimeError('Changed launch prior verifier: '+name)
    namespace={'__name__':'mixel_launch_prior','__file__':str(path)}
    exec(compile(logical,str(path),'exec'),namespace)
    return namespace

def inventory(root, compiler):
    texts={};planned=[];hashes={}
    for name in ORIGINAL:
        path=root/name
        if not path.exists() and not path.is_symlink():
            hashes[name]=None;continue
        path=compiler['safe_source'](root,name)
        text,newline=compiler['canonical'](path.read_bytes())
        texts[name]=(text,newline);hashes[name]=digest(text.encode())
    asset=root/ASSET
    present=asset.exists() or asset.is_symlink()
    if present:
        asset=compiler['safe_source'](root,ASSET)
        text,newline=compiler['canonical'](asset.read_bytes())
        asset_hash=digest(text.encode())
        if asset_hash not in (ASSET_SHA,LEGACY_ASSET_SHA):raise RuntimeError('Changed Mac launch asset')
    matches=[name for name,pins in [('fresh',FRESH),('original',ORIGINAL),('final',FINAL),('previous-final',PREVIOUS_FINAL),('legacy',LEGACY)] if hashes==pins]
    if len(matches)!=1 or present!=(matches[0] in ('final','previous-final','legacy')) or (present and asset_hash!=(LEGACY_ASSET_SHA if matches[0]=='legacy' else ASSET_SHA)):
        raise RuntimeError('Pinned or partial Mac launch profile changed')
    return matches[0],texts

def transform(name,text,restore=False):
    first,last=(FINAL[name],ORIGINAL[name]) if restore else (ORIGINAL[name],FINAL[name])
    if digest(text.encode())==last:return text
    if digest(text.encode())!=first:raise RuntimeError('Changed launch source: '+name)
    pairs=list(reversed(CHANGES[name])) if restore else CHANGES[name]
    for before,after in pairs:
        if restore:before,after=after,before
        if text.count(before)!=1:raise RuntimeError('Changed launch literal: '+name)
        text=text.replace(before,after,1)
    if digest(text.encode())!=last:raise RuntimeError('Changed launch inverse: '+name)
    return text

def transform_legacy(name,text):
    if digest(text.encode())!=LEGACY[name]:raise RuntimeError('Changed legacy launch source: '+name)
    for before,after in reversed(LEGACY_CHANGES.get(name,())):
        if text.count(after)!=1:raise RuntimeError('Changed legacy launch literal: '+name)
        text=text.replace(after,before,1)
    if digest(text.encode())!=ORIGINAL[name]:raise RuntimeError('Changed legacy launch inverse: '+name)
    return text

def transform_previous_final(name,text):
    # The previous final profile differs only in the omitted static tray marker.
    # Its complete inventory was matched before this exact private inverse.
    if digest(text.encode())!=PREVIOUS_FINAL[name]:raise RuntimeError('Changed previous final launch source: '+name)
    return transform_legacy(name,text) if name=='src/tray.rs' else transform(name,text,True)

def validate_prior(root,compiler):
    prior('patch-support-url-log-privacy.py')['apply'](root,restore=True,check=True)
    compiler['apply'](root,check=True,restore=True,before_branding=True)

def apply(root,check=False,restore=False,verify=False):
    root=Path(root).absolute()
    compiler=prior('patch-support-compiler-cleanup.py')
    for parent in (root,*root.parents):
        info=parent.lstat()
        if not stat.S_ISDIR(info.st_mode) or getattr(info,'st_file_attributes',0)&0x400:raise RuntimeError('Unsafe launch source root')
    # Validate the actual supplied tree before copying can hide source ownership.
    compiler['validate_projection_sources'](root)
    state,texts=inventory(root,compiler)
    if state in ('legacy','previous-final') and not restore:raise RuntimeError('Historical launch layer is restore-only')
    resource=compiler['safe_source'](SCRIPTS,'support-macos-gui-launch.rs')
    asset_text,_=compiler['canonical'](resource.read_bytes())
    if digest(asset_text.encode())!=ASSET_SHA:raise RuntimeError('Changed launch source resource')
    if state=='fresh' and not restore:raise RuntimeError('Launch final layer requires complete branding')
    if verify:
        if state not in ('final','previous-final','legacy'):validate_prior(root,compiler)
        else:
            with tempfile.TemporaryDirectory(prefix='mixel-launch-prior-') as temporary:
                stage=Path(temporary).resolve()/'source'
                shutil.copytree(root,stage,symlinks=True,ignore=lambda directory,names:compiler['projection_ignored'](root,directory,names))
                for name,(text,newline) in texts.items():
                    (stage/name).write_bytes((transform_legacy(name,text) if state=='legacy' else transform_previous_final(name,text) if state=='previous-final' else transform(name,text,True)).replace('\n',newline).encode())
                (stage/ASSET).unlink()
                validate_prior(stage,compiler)
    # Complete all exact transformations before the first write.
    planned=[]
    for name,(text,newline) in texts.items():
        result=text if state=='fresh' else (transform_legacy(name,text) if state=='legacy' else transform_previous_final(name,text) if state=='previous-final' else transform(name,text,restore))
        planned.append((root/name,result.replace('\n',newline).encode()))
    writes=0
    for path,raw in planned:
        if not check and path.read_bytes()!=raw:path.write_bytes(raw);writes+=1
    if not check:
        if restore and state in ('final','previous-final','legacy'):(root/ASSET).unlink();writes+=1
        elif not restore and state=='original':
            newline=texts['src/server.rs'][1]
            (root/ASSET).write_bytes(asset_text.replace('\n',newline).encode());writes+=1
    return {'profile':state,'writes':writes,'checkedFiles':len(texts)+int(state=='final')}

def has_layer(root):
    root=Path(root)
    if (root/ASSET).exists() or (root/ASSET).is_symlink():return True
    for name in ORIGINAL:
        path=root/name
        if path.is_file() and any(marker in path.read_bytes() for marker in (b'mixel_gui_launch',b'connect_mixel_gui_peer',b'ACK_SUPERSEDED',b'SupportInviteStartupBridge')):return True
    return False

@contextlib.contextmanager
def previous(root):
    root=Path(root).absolute()
    if not has_layer(root):yield root;return
    assert apply(root,check=True,restore=True,verify=True)['writes']==0
    compiler=prior('patch-support-compiler-cleanup.py')
    before={name:(root/name).read_bytes() for name in (*ORIGINAL,ASSET)}
    with tempfile.TemporaryDirectory(prefix='mixel-launch-consumer-inverse-') as temporary:
        stage=Path(temporary).resolve()/'source'
        shutil.copytree(root,stage,symlinks=True,ignore=lambda directory,names:compiler['projection_ignored'](root,directory,names))
        apply(stage,restore=True)
        try:yield stage
        finally:assert {name:(root/name).read_bytes() for name in before}==before,'Launch projection changed supplied input'


def main():
    parser=argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--root',type=Path,required=True);parser.add_argument('--restore',action='store_true');parser.add_argument('--check',action='store_true')
    parser.add_argument('--before-branding',action='store_true');parser.add_argument('--after-branding',action='store_true')
    args=parser.parse_args()
    if args.before_branding and not (args.restore and args.check):parser.error('--before-branding requires --restore --check')
    if args.after_branding and args.restore:parser.error('--after-branding cannot restore')
    print(apply(args.root,args.check,args.restore,args.before_branding or args.after_branding))
if __name__=='__main__':main()
